from docx import Document
from docx.shared import Pt, RGBColor, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
import re

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1)
sec.top_margin = sec.bottom_margin = Inches(1)
st = doc.styles['Normal']; st.font.name = 'Calibri'; st.font.size = Pt(11)
st.paragraph_format.space_after = Pt(6)
for lvl, sz in ((1, 14), (2, 12), (3, 11)):
    h = doc.styles['Heading %d' % lvl]; h.font.name = 'Calibri'; h.font.size = Pt(sz)
    h.font.color.rgb = RGBColor(0x1F, 0x3A, 0x5F); h.font.bold = True

hp = sec.header.paragraphs[0]
hp.text = 'PRIVILEGED & CONFIDENTIAL — ATTORNEY-CLIENT COMMUNICATION / ATTORNEY WORK PRODUCT — PREPARED IN ANTICIPATION OF LITIGATION'
hp.alignment = WD_ALIGN_PARAGRAPH.CENTER
for r in hp.runs: r.font.size = Pt(8); r.font.bold = True

fp = sec.footer.paragraphs[0]; fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
def _fld(p, code):
    r = p.add_run(); f1 = OxmlElement('w:fldChar'); f1.set(qn('w:fldCharType'), 'begin'); r._r.append(f1)
    r2 = p.add_run(); it = OxmlElement('w:instrText'); it.set(qn('xml:space'), 'preserve'); it.text = code; r2._r.append(it)
    r3 = p.add_run(); f2 = OxmlElement('w:fldChar'); f2.set(qn('w:fldCharType'), 'end'); r3._r.append(f2)
rr = fp.add_run('Greenfield Health Partners — Stark Law Issues Memorandum — Page '); rr.font.size = Pt(8)
_fld(fp, 'PAGE')

def rich(p, text):
    # **bold** and *italic* markup
    parts = re.split(r'(\*\*[^*]+\*\*|\*[^*]+\*)', text)
    for part in parts:
        if part.startswith('**') and part.endswith('**'):
            p.add_run(part[2:-2]).bold = True
        elif part.startswith('*') and part.endswith('*') and len(part) > 2:
            p.add_run(part[1:-1]).italic = True
        elif part:
            p.add_run(part)
    return p

def H(t, l=1): return doc.add_heading(t, level=l)
def P(t, align=None):
    p = rich(doc.add_paragraph(), t)
    if align: p.alignment = align
    return p
def B(t, lvl=0):
    p = doc.add_paragraph(style='List Bullet' if lvl == 0 else 'List Bullet 2'); return rich(p, t)
def N(t):
    p = doc.add_paragraph(style='List Number'); return rich(p, t)

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr(); s = OxmlElement('w:shd')
    s.set(qn('w:val'), 'clear'); s.set(qn('w:color'), 'auto'); s.set(qn('w:fill'), hexcolor); tcPr.append(s)

def T(headers, rows, widths=None, fs=8.5):
    t = doc.add_table(rows=1, cols=len(headers)); t.style = 'Table Grid'; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ''; r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(fs)
        shade(c, 'D9E2F3')
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ''; p = cells[i].paragraphs[0]; rich(p, str(v))
            for r in p.runs: r.font.size = Pt(fs)
            if str(v).startswith('Critical'): shade(cells[i], 'F4CCCC')
            elif str(v).startswith('High'): shade(cells[i], 'FCE5CD')
            elif str(v).startswith('Medium'): shade(cells[i], 'FFF2CC')
            elif str(v).startswith('Lower'): shade(cells[i], 'D9EAD3')
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths): row.cells[i].width = Inches(w)
    doc.add_paragraph()
    return t
